{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/bench && nohup bash -c \"~/miniconda3/envs/mhd_claude/bin/python literature.py C > out_literature/C.log 2>&1; ~/miniconda3/envs/mhd_claude/bin/python literature.py A A_1deg > out_literature/A.log 2>&1\" > /dev/null 2>&1 &\necho started; tail -3 ../runs/da_log.txt; cat ../runs/conv_da0.out",
  "description": "Launch literature replication runs in background"
}

{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude && timeout 1500 bash -c 'until grep -q \"done da1_loo_solo\" runs/da_log.txt; do sleep 20; done'; grep -E \"done|it6|it0 \" runs/da_log.txt | tail -12",
  "description": "Wait for leave-one-out DA jobs to finish",
  "timeout": 1560000
}

{
  "command": "cat /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/shared_notes/codex_external_model_20261016T2334Z_nov23_cme_correction.txt; grep -E \"done|it6 |it0 \" /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/runs/da_log.txt | tail -8; cat /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/runs/conv_da0.out",
  "description": "Read Codex CME note and job progress"
}

{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/runs && python3 -c "
import json
for t in ('da1_loo_sta','da1_loo_earth'):
    h=json.load(open(f'{t}_hist.json'))
    for it in (0,len(h)-1):
        s=h[it]['score']
        print(t, it, {b:(round(v['v_rmse']),round(v['v_corr'],2),round(v['n_med_ratio'],2),round(v['logn_corr'],2)) for b,v in s.items()})
"",
  "description": "Print per-spacecraft scores including MAVEN"
}

{
  "command": "tail -n0 -F /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/monitor/events.log | grep --line-buffered -E \"NOTE|ALARM|HEARTBEAT|Traceback|Error\"",
  "description": "claude-mhd monitor events: collaborator notes, resource alarms, hourly heartbeat",
  "timeout_ms": 1800000
}

{
  "command": "sed -i 's|^Q=../../runs/queue.txt$|Q=${1:-../../runs/queue.txt}|; s|^DONE=../../runs/queue_done.txt$|DONE=${Q%.txt}_done.txt|' queue.sh && cat queue.sh | head -6 && grep -v \"^da2\" ../../runs/queue.txt > ../../runs/q1.tmp && grep \"^da2\" ../../runs/queue.txt > ../../runs/queue2.txt && cat ../../runs/q1.tmp > ../../runs/queue.txt && rm ../../runs/q1.tmp && cat ../../runs/queue2.txt && nohup ./queue.sh ../../runs/queue2.txt > ../../runs/queue2.out 2>&1 & sleep 2; ls ../../runs/*done*",
  "description": "Start a second parallel DA queue"
}

{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/bench && cat out_literature/C.log | tail -30; tail -2 out_literature/C_1deg/stdout.txt 2>/dev/null",
  "description": "Check Pizzo 1978 replication results"
}

{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/bench && ls out_literature/ ; ps -eo pid,etime,args | grep -E \"literature|C_1deg\" | grep -v grep | head",
  "description": "Check whether literature runs are active"
}

{
  "command": "mkdir -p out_literature && nohup bash -c \"~/miniconda3/envs/mhd_claude/bin/python literature.py C > out_literature/C.log 2>&1; ~/miniconda3/envs/mhd_claude/bin/python literature.py A A_1deg > out_literature/A.log 2>&1\" > out_literature/chain.log 2>&1 &\nsleep 20; ls out_literature; tail -2 out_literature/C_1deg/stdout.txt 2>/dev/null",
  "description": "Relaunch literature replication runs"
}
